 $$Shell("ObjApp")$$Shell("XAppName") 'rseg';		#endif	#endif	/* Include the separately compiled resources */	include "CalcUtilities.rsrc" not 'ckid';#else	#if qDebug | qPerform		include kDebugRsrcName not 'ckid';	#endif	include kDialogRsrcName not 'ckid';	include kGeneralRsrcName not 'ckid';	include kPrintingRsrcName not 'ckid';#endif // !THINK_Rez//--------------------------------------------------------------------------------------------------// CONSTANTS //--------------------------------------------------------------------------------------------------// Finder Information// ------------------#if !defined(THINK_Rez) && !defined(MW_Rez)#define kApplicationName	$$Shell("XAppName")#else#define kApplicationName	TARGET_APPLICATION_NAME#endif // !THINK_Rez#define kSignature			'SS14'			// Application signature #define kFileType			'SF01'			// Data file type #define kStationery			'sF01'			// Stationery file type // Bundle Constants// ------------------#define kBundleID						128#define kApplicationID					128#define kDocumentID						129#define kStationeryID					130// Constants for Menu IDs// ----------------------#define mDynamicPopupsMenu	4// Command Numbers For Menu Items// ------------------------------#define cCommandHandledByApplication	400#define cCommandHandledByDocument		401#define cCommandHandledByView			402#define cTrackerCommand					403// STR# resources// --------------#define kDynamicPopupsMenuHelp				1000#define kDynamicPopupsWindowTitles			1001// Text styles// --------------#define kSystemTextStyle				1000// 'View' resources// --------------#define kDynamicPopupsWindowID				kDefaultWindowID// Memory Management Resources// ---------------------------#define kDynamicPopupsSeg	1000#define kDynamicPopupsMem	1000#define kDynamicPopupsRes	1000//--------------------------------------------------------------------------------------------------// RESOURCES FOR MENUS //--------------------------------------------------------------------------------------------------//--------------------------------------------------------------------------------------------------// Menu Bars //--------------------------------------------------------------------------------------------------resource 'MBAR' (kMBarDisplayed,#if qNames"DynamicPopup",#endif	purgeable) {	{ mApple; mFile; mEdit }};//--------------------------------------------------------------------------------------------------// Menus //--------------------------------------------------------------------------------------------------include kDefaultRsrcName 'CMNU' (mApple);	// Grab the default Apple menusinclude kDefaultRsrcName 'CMNU' (mFile);		// Grab the default File menusinclude kDefaultRsrcName 'CMNU' (mEdit);		// Grab the default Edit menuresource 'CMNU' (mBuzzwords,#if qNames"Buzzwords",#endifpurgeable) {	mBuzzwords,	textMenuProc,	EnablingManagedByMacApp,	enabled,	"Buzzwords",	 {	/* array: 13 elements */		"Page Setup Change",	noIcon,	noKey,	noMark, plain, cChangePrinterStyle;		"Typing",				noIcon,	noKey,	noMark,	plain, cTyping;		"Tracker Command",		noIcon,	noKey,	noMark, plain, cTrackerCommand;	}};//--------------------------------------------------------------------------------------------------// Balloon Help Resources for Menus //--------------------------------------------------------------------------------------------------#include "HelpStrings.r"#if !qCarboninclude kDefaultRsrcName  'hmnu' (mFile);	include kDefaultRsrcName  'hmnu' (mEdit);	resource 'STR#' (kDynamicPopupsMenuHelp, purgeable) { 	{		"No help yet for this  item",		"Help For Menu Title",		"Help For First Menu Item",		"Help For Second Menu Item",		"Help For Third Menu Item",	}};resource 'hmnu' (mDynamicPopupsMenu) {	HelpMgrVersion,	hmDefaultOptions,	0, // balloon definition function 	0, // variation code 		// Missing items 	HMStringResItem 	{		kDynamicPopupsMenuHelp,1,		kDynamicPopupsMenuHelp,1,		kDynamicPopupsMenuHelp,1,		kDynamicPopupsMenuHelp,1,	},		// Title and items 	{			// Title 		HMStringResItem 		{			kDynamicPopupsMenuHelp,2,			kDynamicPopupsMenuHelp,2,			kDynamicPopupsMenuHelp,2,			kDynamicPopupsMenuHelp,2,		},		// First Item 		HMStringResItem 		{			kDynamicPopupsMenuHelp,3,			kDynamicPopupsMenuHelp,3,			kDynamicPopupsMenuHelp,3,			kDynamicPopupsMenuHelp,3,		},		// Second Item		HMStringResItem 		{			kDynamicPopupsMenuHelp,4,			kDynamicPopupsMenuHelp,4,			kDynamicPopupsMenuHelp,4,			kDynamicPopupsMenuHelp,4,		},		// Third Item		HMStringResItem 		{			kDynamicPopupsMenuHelp,5,			kDynamicPopupsMenuHelp,5,			kDynamicPopupsMenuHelp,5,			kDynamicPopupsMenuHelp,5,		},	}};#endif // !qCarbon//--------------------------------------------------------------------------------------------------// RESOURCES FOR VIEWS, DIALOGS, ALERTS etc. //--------------------------------------------------------------------------------------------------//--------------------------------------------------------------------------------------------------// About Box//--------------------------------------------------------------------------------------------------resource 'DITL' (phAboutApp,#if qNames"phAboutApp",#endif	purgeable) {	 {	/* array DITLarray: 3 elements */		/* [1] */		{160, 182, 180, 262},		Button {			enabled,			"OK"		};		/* [2] */		{10, 75, 150, 316},		StaticText {			disabled,			"This application demonstrates the use of dynamic popup menus."			"\n\n"			WRITTEN_WITH_MACAPP		};		/* [3] */		{10, 20, 42, 52},		Icon {			disabled,			1		}	}};include kDefaultRsrcName  'ALRT' (phAboutApp);		// Grab the default about boxinclude kDefaultRsrcName	'aete' (0);					// Grab the default AppleEvent terminologyinclude kDefaultRsrcName  'STR#' (kDefaultCredits);	// Grab the default credits//--------------------------------------------------------------------------------------------------// MultiFinderª information//--------------------------------------------------------------------------------------------------/* Additional size deltas to be added to partition size */#if qNames#define kNamesSizeDelta 75#else#define kNamesSizeDelta 0#endif#if qDebug#define kDebugSizeDelta 0#else#define kDebugSizeDelta 0#endif#define kModelFarSizeDelta 0#ifndef MW_Rez					// MW projects supply size resource for usresource 'SIZE' (-1) {	saveScreen,	acceptSuspendResumeEvents,	enableOptionSwitch,	canBackground,	doesActivateOnFGSwitch,	backgroundAndForeground,	dontGetFrontClicks,	ignoreAppDiedEvents,	is32BitCompatible,	isHighLevelEventAware,	localAndRemoteHLEvents,	notStationeryAware,					reserved,	reserved,	reserved,	reserved,		/* Suggested partition size */	(2000 + kNamesSizeDelta + kDebugSizeDelta + kModelFarSizeDelta) * 1024,		/* Minimum partition size */	(1800 + kNamesSizeDelta + kDebugSizeDelta + kModelFarSizeDelta) * 1024};#endif // !MW_Rez//--------------------------------------------------------------------------------------------------// Icons//--------------------------------------------------------------------------------------------------include kDefaultRsrcName  'ICN#' (kApplicationID);	// MacApp Family large black & white	include kDefaultRsrcName  'ICN#' (kDocumentID);		// MacApp Document large black & whiteinclude kDefaultRsrcName  'ICN#' (kStationeryID);	// MacApp Stationery large black & white	include kDefaultRsrcName  'ics#' (kApplicationID);	// MacApp Family small black & white	include kDefaultRsrcName  'ics#' (kDocumentID);		// MacApp Document small black & whiteinclude kDefaultRsrcName  'ics#' (kStationeryID);	// MacApp Stationery small black & whiteinclude kDefaultRsrcName  'ics4' (kApplicationID);	// MacApp Family small 4 bitinclude kDefaultRsrcName  'ics4' (kDocumentID);		// MacApp Document small 4 bitinclude kDefaultRsrcName  'ics4' (kStationeryID);	// MacApp Stationery small 4 bitinclude kDefaultRsrcName  'ics8' (kApplicationID);	// MacApp Family small 4 bitinclude kDefaultRsrcName  'ics8' (kDocumentID);		// MacApp Document small 4 bitinclude kDefaultRsrcName  'ics8' (kStationeryID);	// MacApp Stationery small 4 bitinclude kDefaultRsrcName  'icl4' (kApplicationID);	// MacApp Family large 4 bitinclude kDefaultRsrcName  'icl4' (kDocumentID);		// MacApp Document large 4 bitinclude kDefaultRsrcName  'icl4' (kStationeryID);	// MacApp Stationery large 4 bitinclude kDefaultRsrcName  'icl8' (kApplicationID);	// MacApp Family large 8 bitinclude kDefaultRsrcName  'icl8' (kDocumentID);		// MacApp Document large 8 bitinclude kDefaultRsrcName  'icl8' (kStationeryID);	// MacApp Stationery large 8 bit//--------------------------------------------------------------------------------------------------// Memory usage information for DynamicPopups//--------------------------------------------------------------------------------------------------// See UMemory.h// -------------//--------------------------------------------------------------------------------------------------// Icons, Bundles and FRefsÉÊOh my! (don't forget the Signature)//--------------------------------------------------------------------------------------------------type kSignature as 'STR ';resource kSignature (0,#if qNames"Signature",#endif	purgeable) {	"DynamicPopups, "APPLE_LONG_COPYRIGHT};resource 'FREF' (kApplicationID,#if qNames"DynamicPopups Application",#endif	purgeable) {	'APPL',	0,	""};resource 'BNDL' (kBundleID,#if qNames"DynamicPopups",#endif	purgeable) {	kSignature,	0,	{		'ICN#',		{ 0, kApplicationID },		'FREF',		{ 0, kApplicationID }	}};resource 'open' (kBundleID){	kSignature, {}};resource 'kind' (kBundleID){	kSignature,	verUS,	{		ftApplicationName, 	"Skeleton",	}};//--------------------------------------------------------------------------------------------------//  Version resources//--------------------------------------------------------------------------------------------------// The revision of this particular fileRESOURCE 'vers' (1,#if qNames"File Version",#endif	purgeable) {	0x01,	0x01,	development,	0x00,	verUs,	"1.1",	"DynamicPopups 1.1, "APPLE_LONG_COPYRIGHT};include kDefaultRsrcName  'vers' (2);		// Overall package#ifndef MW_Rez		include "DynamicPopups.view" not 'vers';#endif